INSERT INTO joints (slug, name, region, joint_type, description, display_order) VALUES
  ('scapulothoracic', 'Scapulothoracic', 'Shoulder girdle', 'Functional (physiological)', 'The gliding articulation of the scapula on the posterior thoracic wall. Not a true synovial joint, but its coordinated motion (scapulohumeral rhythm) is essential to full overhead reach.', 0),
  ('glenohumeral', 'Glenohumeral', 'Shoulder', 'Ball-and-socket (synovial)', 'The shoulder joint proper: the humeral head in the shallow glenoid fossa. The most mobile — and least stable — joint in the body, relying on the rotator cuff for dynamic stability.', 1),
  ('elbow', 'Elbow', 'Arm', 'Hinge (synovial)', 'The humero-ulnar and humero-radial hinge that flexes and extends the forearm.', 2),
  ('forearm', 'Forearm', 'Forearm', 'Pivot (radio-ulnar)', 'The proximal and distal radio-ulnar joints, which together rotate the forearm into pronation and supination.', 3),
  ('wrist', 'Wrist', 'Wrist', 'Condyloid (synovial)', 'The radiocarpal joint, allowing flexion/extension and radial/ulnar deviation of the hand.', 4),
  ('fingers', 'Fingers', 'Hand', 'Condyloid / hinge (synovial)', 'The metacarpophalangeal (MP) and interphalangeal (PIP/DIP) joints of the digits.', 5),
  ('spine', 'Spine', 'Trunk', 'Cartilaginous / facet (synovial)', 'The intervertebral and zygapophyseal (facet) joints of the vertebral column, permitting extension, flexion and lateral flexion of the trunk.', 6)
ON CONFLICT (slug) DO NOTHING;

