  ('pronator-quadratus', 'forearm', 'pronation', TRUE)
) AS v(muscle_slug, joint_slug, action_slug, is_prime_mover)
JOIN muscles m ON m.slug = v.muscle_slug
JOIN joints  j ON j.slug = v.joint_slug
JOIN actions a ON a.slug = v.action_slug
ON CONFLICT (muscle_id, joint_id, action_id) DO NOTHING;

